}


Action: run_sql({'query': 'WITH restaurant_metrics AS (\n  SELECT e.gmap_id, e.avg_rating,\n         COUNT(v.violation_id) AS total_violation_rows,\n         COALESCE(SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END), 0) AS critical_violation_rows\n  FROM establishments e\n  JOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\n  LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n  LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n  WHERE e.avg_rating IS NOT NULL\n  GROUP BY e.gmap_id, e.avg_rating\n)\nSELECT COUNT(*) AS matched_restaurants_with_rating,\n       corr(avg_rating, total_violation_rows) AS pearson_rating_total_violations,\n       corr(avg_rating, critical_violation_rows) AS pearson_rating_critical_violations,\n       avg(avg_rating) AS mean_rating,\n       avg(total_violation_rows) AS mean_total_violation_rows,\n       avg(critical_violation_rows) AS mean_critical_violation_rows\nFROM restaurant_metrics;'})

Action: plot_chart({'chart_type': 'scatter', 'query': 'WITH restaurant_metrics AS (\n  SELECT e.gmap_id, e.name, e.avg_rating,\n         COUNT(v.violation_id) AS total_violation_rows\n  FROM establishments e\n  JOIN inspections i ON e.slchd_establishment_key = i.slchd_establishment_key\n  LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n  WHERE e.avg_rating IS NOT NULL\n  GROUP BY e.gmap_id, e.name, e.avg_rating\n)\nSELECT avg_rating, total_violation_rows\nFROM restaurant_metrics;', 'title': 'Google Rating vs. Total Cited Violation Rows (Matched Restaurants)', 'x': 'avg_rating', 'y': 'total_violation_rows'})

